mapper.select:
SELECT
FROM education_achievements achievement JOIN lecture_improvement_achievement_details detail ON detail.achievement_id = achievement.achievement_id JOIN users teacher ON teacher.user_id = achievement.teacher_user_id WHERE achievement.achievement_type = 'LECTURE_IMPROVEMENT' AND achievement.deleted_yn = 'N'
ORDER BY achievement.achievement_date DESC, achievement.achievement_id DESC LIMIT #{criteria.safePageSize} OFFSET #{criteria.offset}

mapper.update:
UPDATE lecture_improvement_achievement_details
SET performance_content = #{achievementContent},
    academic_year = #{academicYear},
    semester_code = #{semesterCode}
WHERE achievement_id = #{achievementId}
